mapper.select:
SELECT t2.`name` AS curtain_name, t3.`name` AS structure_name, t4.`name` AS element_name, t1.id, t1.curtain_id, t1.structure_id, t1.element_id, t1.creator, t1.create_time, t1.updater, t1.update_time FROM zc_curtain_template t1 JOIN zc_curtain t2 ON t1.curtain_id = t2.id AND t2.deleted = 0 JOIN zc_curtain_structure t3 ON t1.structure_id = t3.id AND t3.deleted = 0 JOIN zc_curtain_structure_element t4 ON t1.element_id = t4.id AND t4.deleted = 0 WHERE t1.deleted = 0
AND t1.curtain_id = #{reqVO.curtainId}
AND t1.structure_id = #{reqVO.structureId}
AND t1.element_id = #{reqVO.elementId}
ORDER BY t1.id DESC
